package org.kanger;
import java.util.*;
import org.kanger.ContextProductionCapture.Source;
import org.kanger.ContextProductionCapture.Support;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextUniversalInputResiduals.*;
import org.kanger.ContextUniversalGroupedRounds.*;
import org.kanger.ContextUniversalGroupedRounds.Result;
import org.kanger.ContextWitnessResultTransport.*;

/** Diagnostic authoring harness, not a product/family qualification gate. Numeric fixtures only. */
public final class ContextUniversalWorkProfileRunner {
    static final int WORK=64000000;static int checks;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static String support(Support s,Map<Source,String> rows){List<String> out=new ArrayList<>();for(Source source:s.sources){String label=rows.get(source);require(label!=null,"Actual original physical row required for normalized diagnostic signature");out.add(label);}Collections.sort(out);return out+"@"+s.depth;}
    static String value(SemanticTermSnapshot s){Object n=s.materialize().getValue();require(n instanceof Number,"Profile comparison is intentionally limited to numeric fixtures");return s.getType().name()+":"+n;}
    static String literal(Literal l,Map<Integer,Integer> vars,Map<Source,String> rows){List<String> args=new ArrayList<>();for(Term t:l.arguments){if(t.variable>=0)args.add("v"+vars.get(t.variable));else if(t.origin!=null){require(rows.containsKey(t.origin.source),"Actual Origin source required");args.add("origin:"+rows.get(t.origin.source)+":"+t.origin.binder);}else args.add(value(t.value));}return (l.positive?"+":"-")+l.predicate+args;}
    static String clause(Residual r,Map<Source,String> rows){if(r==null)return "EMPTY";List<Integer> ids=new ArrayList<>(r.variables);Collections.sort(ids);require(ids.size()<=2,"Profile fixture alpha vocabulary");List<String> variants=new ArrayList<>();for(int n=0;n<(ids.size()==2?2:1);++n){Map<Integer,Integer> v=new HashMap<>();for(int i=0;i<ids.size();++i)v.put(ids.get(i),n==0?i:1-i);List<String> ls=new ArrayList<>();for(Literal l:r.literals)ls.add(literal(l,v,rows));Collections.sort(ls);variants.add(ls.toString());}Collections.sort(variants);return variants.get(0);}
    static List<String> packet(Packet p,Map<Source,String> rows){List<String> out=new ArrayList<>();for(Item i:p.items)for(Support s:i.proofs)out.add(clause(ContextUniversalInputResiduals.fact(i,()->{}),rows)+support(s,rows));Collections.sort(out);return out;}
    static List<String> units(ContextUniversalSignedUnitExchange.Exchange e,Map<Source,String> rows){List<String> out=new ArrayList<>();if(e!=null)for(ContextUniversalSignedUnitExchange.Unit u:e.units)out.add(clause(u.clause,rows)+support(u.support,rows));Collections.sort(out);return out;}
    static List<String> compounds(ContextUniversalCompoundExchange.Exchange e,Map<Source,String> rows){List<String> out=new ArrayList<>();for(ContextUniversalCompoundExchange.ResidualProof p:e.clauses)out.add(clause(p.clause,rows)+support(p.support,rows));Collections.sort(out);return out;}
    static Map<String,Object> semantic(Result r,Map<Source,String> rows){Map<String,Object> out=new LinkedHashMap<>();out.put("status",r.status.name());out.put("phase",r.phase);out.put("reason",r.reason);out.put("completed",r.completedRounds);out.put("history",r.history.size());out.put("refutations",r.refutations.size());out.put("outputNull",r.output==null);if(r.output!=null){out.put("fixed",packet(r.output.packet,rows));out.put("units",units(r.symbolicOutput,rows));out.put("compounds",compounds(r.compoundOutput,rows));List<Object> rounds=new ArrayList<>();for(Round n:r.history){Map<String,Object> step=new LinkedHashMap<>();step.put("number",n.number);step.put("flags",Arrays.asList(n.commonChanged,n.privateChanged,n.symbolicChanged,n.compoundChanged,n.barrier.localChanged));step.put("inputFixed",packet(n.input,rows));step.put("outputFixed",packet(n.barrier.packet,rows));step.put("inputUnits",units(n.symbolicInput,rows));step.put("outputUnits",units(n.symbolicOutput,rows));step.put("inputCompounds",compounds(n.compoundInput,rows));step.put("outputCompounds",compounds(n.compoundOutput,rows));List<Object> cuts=new ArrayList<>();for(ContextUniversalFrozenConstraints.Result c:n.checks.values()){List<String> proofs=new ArrayList<>();for(ContextUniversalFrozenConstraints.Proof p:c.proofs)proofs.add(clause(p.clause,rows)+support(p.support,rows));Collections.sort(proofs);cuts.add(proofs);}step.put("cuts",cuts);rounds.add(step);}out.put("rounds",rounds);}return out;}
    static void run(String fixture)throws Exception {
        boolean budget=fixture.equals("budget");require(budget||fixture.equals("stable"),"Known diagnostic fixture required");Snapshot x=ContextUniversalGroupedRoundsRunner.bind(true,"!anchor(1); !@u p(u);"),a=ContextUniversalGroupedRoundsRunner.bind(false,budget?"!@u (p(u)&&b(u)->r(u))&&(p(u)&&r(u)->s(u));":"!@u p(u)&&b(u)->r(u);"),b=ContextUniversalGroupedRoundsRunner.bind(false,"!b(1);");List<Snapshot> supplied=Arrays.asList(a,b);Packet common=ContextPrivateWitnessPoolRunner.common(x);ContextUniversalCompoundExchange.Exchange initial=ContextUniversalGroupedRoundsRunner.exchange(x,supplied,common,Collections.emptyMap());ContextUniversalSignedUnitExchange.Exchange units=ContextUniversalGroupedRoundsRunner.units(initial);
        Map<Source,String> rows=new HashMap<>();List<String> originals=new ArrayList<>();int context=0;for(Snapshot view:Arrays.asList(x,a,b)){int row=0;for(ContextProductionNativeBinding.Entry entry:view.primary){String label=(context==0?"X":context==1?"A":"B")+row++;require(rows.put(entry.source,label)==null,"Do not collapse duplicate physical source occurrences");originals.add(label+":"+entry.statement);}++context;}
        ContextUniversalWorkProfile.reset();Result r;Map<String,Object> profile;try{r=ContextUniversalGroupedRounds.run(x,supplied,common,Collections.emptyMap(),units,initial,ContextUniversalGroupedRoundsRunner.limits(16),ContextUniversalGroupedRoundsRunner.local(),8,WORK);}finally{profile=ContextUniversalWorkProfile.finish();}
        if(budget)require(r.status==Status.INCOMPLETE&&r.phase.equals("certificate-binding")&&r.completedRounds==2&&r.history.isEmpty()&&r.refutations.isEmpty()&&r.output==null&&r.symbolicOutput==null&&r.compoundOutput==null&&r.reason.contains("Ground transport work limit"),"Same concrete bounded refusal, no prefix");else{require(r.status==Status.STABLE_GROUPED_POOLS,"Stable numeric control required: "+r.reason);ContextUniversalGroupedLocalRounds.Limits local=r.history.get(0).certificates.values().iterator().next().limits;ContextUniversalGroupedChainAudit.Inspection audit=ContextUniversalGroupedChainAudit.inspect(x,supplied,common,Collections.emptyMap(),units,initial,ContextUniversalGroupedRoundsRunner.limits(16),local,8,r,WORK);require(audit.audited,audit.phase+": "+audit.reason);}
        Map<String,Object> out=new LinkedHashMap<>();out.put("fixture",fixture);out.put("originals",originals);out.put("workLimit",WORK);out.put("semantic",semantic(r,rows));out.put("profile",profile);out.put("checks",checks);System.out.println("WORK_PROFILE_RESULT "+ContextUniversalWorkProfile.json(out));
    }
    static void selfTest(){ContextUniversalWorkProfile.reset();int[] left={3};Runnable work=ContextUniversalWorkProfile.root(()->{if(--left[0]<0)throw new IllegalStateException("toy work limit");});Object object=new Object();for(int i=0;i<2;++i)try(ContextUniversalWorkProfile.Scope scope=ContextUniversalWorkProfile.enter("toy",object,work)){work.run();}boolean refused=false;try(ContextUniversalWorkProfile.Scope scope=ContextUniversalWorkProfile.enter("outer",object,work)){try(ContextUniversalWorkProfile.Scope inner=ContextUniversalWorkProfile.enter("inner",object,work)){work.run();work.run();}}catch(IllegalStateException expected){refused=true;}Map<String,Object> p=ContextUniversalWorkProfile.finish();require(refused&&p.get("attemptedTicks").equals(4L)&&p.get("acceptedTicks").equals(3L)&&p.get("failed").equals(true),"Exact counter including failing attempt");List<?> scopes=(List<?>)p.get("scopes");Map<?,?> toy=(Map<?,?>)scopes.get(0);require(toy.get("calls").equals(2L)&&toy.get("uniqueTargets").equals(1)&&toy.get("repeatAfterCompletedCalls").equals(1L)&&toy.get("inclusiveTicks").equals(2L),"Identity repetitions and exclusive/inclusive accounting");System.out.println("CONTEXT_UNIVERSAL_WORK_PROFILE_SELF_PASS checks="+checks);}
    static void validationCounter(){ContextUniversalWorkProfile.reset();Runnable work=ContextUniversalWorkProfile.root(()->{});boolean refused=false;try{ContextUniversalFrozenConstraints.check(null,64,work);}catch(IllegalStateException expected){refused=true;}Map<String,Object> p=ContextUniversalWorkProfile.finish();List<?> stats=(List<?>)p.get("scopes");require(refused&&stats.size()==1,"Actual invalid native proof frame must refuse");Map<?,?> frame=(Map<?,?>)stats.get(0);require(frame.get("completedTargets").equals(0)&&frame.get("abortedCalls").equals(1L)&&p.get("attemptedTicks").equals(0L),"Rejected validation must not count as successfully completed");System.out.println("CONTEXT_UNIVERSAL_WORK_PROFILE_VALIDATION_PASS checks="+checks);}
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("work-profile-").toString());if(args.length==1&&args[0].equals("self-test"))selfTest();else if(args.length==1&&args[0].equals("validation-counter"))validationCounter();else{require(args.length==1,"One fixture argument required");run(args[0]);}System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
